//! 🧩️ Authored fixed contextual fields retain their original payload and scalar source through native singleton publication.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
/// 🧬️ The authored transformation reads only fixed original fields and retains the exact inverse selector.
pub trait OriginalSingleTransform:SingleFieldPath{type Payload:Send+Sync+'static;type Context:NativeScalar;type Inverse:NativeScalar;fn context(p:&Self::Payload)->Self::Context;fn valid_payload(p:&Self::Payload)->bool;fn value(p:&Self::Payload,o:RetainedCloneRef<'_,EnergyModelSnapshot>)->Self::Scalar;fn inverse(c:Self::Context,v:Self::Scalar)->Self::Inverse;}
pub struct TransformedSinglePreparation<S:OriginalSingleTransform>{input:Option<RetainedCloneBinding>,original:Option<RetainedCloneBinding>,body:Option<usize>,context:Option<S::Context>,source:ManuallyDrop<Option<RetainedCloneSource<S::Scalar>>>,core:Option<Box<SingleFieldPreparation<S>>>,phase:u8,closing:bool}
impl<S:OriginalSingleTransform> TransformedSinglePreparation<S>{fn source(&self)->Result<RetainedCloneRef<'_,S::Scalar>,ValueError>{Ok(self.source.as_ref().ok_or_else(invalid)?.borrow())}fn core(&self)->Result<&SingleFieldPreparation<S>,ValueError>{self.core.as_deref().ok_or_else(invalid)}fn core_mut(&mut self)->Result<&mut SingleFieldPreparation<S>,ValueError>{self.core.as_deref_mut().ok_or_else(invalid)}}
impl<S:OriginalSingleTransform> RowFieldPreparation for TransformedSinglePreparation<S>{
 type Input=S::Payload;type Inverse=S::Inverse;
 fn new()->Self{Self{input:None,original:None,body:None,context:None,source:ManuallyDrop::new(None),core:None,phase:0,closing:false}}
 fn check(&self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>)->Result<(),ValueError>{if key.is_some(){return Err(invalid());}p.check_binding(&self.input)?;o.check_binding(&self.original)?;if let Some(c)=self.core.as_ref(){c.check(self.source()?,o)?;}Ok(())}
 fn demand(&self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>=99||self.body.is_some_and(|b|b!=body){return Err(invalid());}self.check(p,key,o)?;match self.phase{
 0=>nested(scalar(o.binding_copy_bytes()+size_of::<usize>()),1),1=>nested(scalar(p.binding_copy_bytes()),2*size_of::<Option<S::Context>>()+2*size_of::<Self::Input>()+1),2=>Ok(scalar(2*size_of::<Self::Input>()+2)),3=>{let d=RetainedCloneSource::<S::Scalar>::owned_constructor_demand::<()>();Ok(RetirementDemand{copy_bytes:2*size_of::<Self::Input>()+4*size_of::<S::Scalar>()+RetainedCloneSource::<S::Scalar>::constructor_copy_bytes()+2*size_of::<Option<RetainedCloneSource<S::Scalar>>>()+1,capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})},4=>Ok(birth::<SingleFieldPreparation<S>>()),5=>self.core()?.demand(self.source()?,o,body),_=>Err(invalid())}}
 fn advance(&mut self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(p,key,o,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut r=receipt(d);match self.phase{
 0=>{r=add(o.bind(&mut self.original,child(g,1+size_of::<usize>()))?.ok_or_else(invalid)?,1+size_of::<usize>())?;self.body=Some(body);self.phase=1;},1=>{let extra=2*size_of::<Option<S::Context>>()+2*size_of::<Self::Input>()+1;r=add(p.bind(&mut self.input,child(g,extra))?.ok_or_else(invalid)?,extra)?;self.context=Some(S::context(p.get()));self.phase=2;},2=>{self.phase=if S::valid_payload(p.get()){3}else{99};},3=>{let extra=2*size_of::<Self::Input>()+4*size_of::<S::Scalar>()+2*size_of::<Option<RetainedCloneSource<S::Scalar>>>()+1;let value=S::value(p.get(),o);let(source,progress)=RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-extra,..g}).map_err(|(e,_,())|tag(e,extra))?;*self.source=Some(source);r=add(progress,extra)?;self.phase=4;},4=>{self.core=Some(Box::new(SingleFieldPreparation::new()));self.phase=5;},5=>{let v=self.source.as_ref().ok_or_else(invalid)?.borrow();return self.core.as_mut().ok_or_else(invalid)?.advance(v,o,body,g);},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,r,"original contextual Energy singleton")?;Ok(if self.ready(){RetainedCloneStep::Complete(r)}else{RetainedCloneStep::Progress(r)})}
 fn ready(&self)->bool{!self.closing&&(self.phase==99||self.core.as_ref().is_some_and(|c|c.ready()))}fn outcome(&self)->Option<RowOutcome>{if self.phase==99{Some(RowOutcome::Invalid)}else{self.core.as_ref().and_then(|c|c.outcome())}}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{self.core()?.take_demand()}fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(EnergyModelDiff,RetainedCloneProgress)>,ValueError>{self.core_mut()?.take(g)}
 fn inverse_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{RowFieldPreparation::inverse_demand(self.core()?,b)}fn prepare_inverse(&mut self,b:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{RowFieldPreparation::prepare_inverse(self.core_mut()?,b,g)}fn inverse_ready(&self)->bool{self.core.as_ref().is_some_and(|c|RowFieldPreparation::inverse_ready(&**c))}
 fn take_inverse_demand(&self)->Result<RetirementDemand,ValueError>{nested(self.core()?.inverse_demand()?,2*size_of::<Self::Inverse>()+2*size_of::<S::Scalar>()+size_of::<S::Context>())}
 fn take_inverse(&mut self,g:RetainedCloneGrant)->Result<Option<(Self::Inverse,RetainedCloneProgress)>,ValueError>{let d=self.take_inverse_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None);}let extra=2*size_of::<Self::Inverse>()+2*size_of::<S::Scalar>()+size_of::<S::Context>();let c=self.context.ok_or_else(invalid)?;let(value,p)=self.core_mut()?.take_inverse(child(g,extra))?.ok_or_else(invalid)?;Ok(Some((S::inverse(c,value),add(p,extra)?)))}
 fn begin_close(&mut self){self.closing=true;if let Some(c)=self.core.as_mut(){c.begin_close();}}
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}let body=self.body.unwrap_or(body);if self.core.is_some(){return cursor_demand(&self.core,body);}if let Some(s)=self.source.as_ref(){return if s.terminal_is_empty(){Ok(scalar(2*size_of::<Option<RetainedCloneSource<S::Scalar>>>()))}else{s.next_close_demand(body)};}if self.context.is_some(){return Ok(scalar(2*size_of::<Option<S::Context>>()));}RetainedCloneBinding::close_demand(if self.input.is_some(){&self.input}else{&self.original},body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(self.body.unwrap_or(g.maximum_copy_bytes))?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,..g};if self.core.is_some(){return close_cursor(&mut self.core,g).map(RetainedCloneStep::Progress);}if let Some(s)=self.source.as_mut(){if s.terminal_is_empty(){drop(self.source.take());return Ok(RetainedCloneStep::Progress(receipt(d)));}return s.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if self.context.is_some(){self.context=None;return Ok(RetainedCloneStep::Progress(receipt(d)));}let p=RetainedCloneBinding::close_one(if self.input.is_some(){&mut self.input}else{&mut self.original},g)?.progress();Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.core.is_none()&&self.source.is_none()&&self.input.is_none()&&self.original.is_none()&&self.context.is_none()}
}
impl<S:OriginalSingleTransform> Drop for TransformedSinglePreparation<S>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"original contextual singleton retains source or candidate custody");if empty{unsafe{ManuallyDrop::drop(&mut self.source);}}}}
impl<S:SingleFieldPath> CursorClose for SingleFieldPreparation<S>{fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{Self::close_demand(self,b)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Self::close_step(self,g)}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}}
